import {WORLD, slots, clamp, ease, transform, project, nearestSlot, allocateMemories} from './world.mjs';
import {memories} from './fixtures.mjs';

const $ = id => document.getElementById(id);
const canvas = $('scene'), ctx = canvas.getContext('2d', {alpha:false});
const view = {w:innerWidth,h:innerHeight};
const origin = {x:760,y:565,zoom:1};
let camera={...origin}, tween=null, selection=null, butterfly=null, returnCamera=null;
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches, running=true, loaded=false;
let frameID=0, lastTime=0, recording=null, demo=null, lastFocus=null;
const assets={}, allocation=allocateMemories(memories), memoryBySlot=new Map();
for(const m of memories) memoryBySlot.set(allocation.assignments[m.id], m);
const visibleSlots=slots.filter(s=>memoryBySlot.has(s.id));
const metrics={frames:0,slowFrames:0,maxFrameMs:0};
function resize(){view.w=innerWidth;view.h=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(view.w*dpr);canvas.height=Math.round(view.h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
$('quiet').checked=reduced;document.body.dataset.reduced=String(reduced);
$('quiet').addEventListener('change',()=>{reduced=$('quiet').checked;document.body.dataset.reduced=String(reduced);if(reduced){if(tween)camera={...tween.to};tween=null;if(selection)showMemory();}schedule()});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{reduced=e.matches;$('quiet').checked=reduced;document.body.dataset.reduced=String(reduced);if(reduced){if(tween)camera={...tween.to};tween=null;if(selection)showMemory();}schedule()});

function move(to,duration=1300){tween=reduced?null:{from:{...camera},to:{...camera,...to},start:performance.now(),duration};if(reduced)camera={...camera,...to};schedule()}
function closePanels(){for(const id of ['options','flower-list','notice'])$(id).hidden=true;$('open-menu').setAttribute('aria-expanded','false')}
function reset(){closeMemory(false);closePanels();move(origin)}
function showMemory(){if(!selection)return;const m=memoryBySlot.get(selection.id);$('memory-date').textContent=`${m.date} · 水畔`;$('memory-title').textContent=m.title;$('memory-body').textContent=m.body;$('memory-quote').textContent=m.quote;$('memory').hidden=false;document.body.classList.add('has-memory');if(!demo)$('close-memory').focus({preventScroll:true})}
function selectFlower(slot){if(!slot)return;lastFocus=document.activeElement;closePanels();$('memory').hidden=true;document.body.classList.remove('has-memory');returnCamera={...camera};selection=slot;const t=transform(view,camera);const p=project(slot,t);butterfly={start:performance.now(),from:{x:p.x-95,y:p.y-125},duration:1450};move({x:slot.x,y:slot.y+105,zoom:Math.min(camera.zoom+0.16,1.45)},1300);if(reduced)showMemory()}
function closeMemory(restore=true){selection=null;butterfly=null;$('memory').hidden=true;document.body.classList.remove('has-memory');if(restore&&returnCamera)move(returnCamera,1050);returnCamera=null;if(lastFocus?.isConnected&&lastFocus.getClientRects().length)lastFocus.focus({preventScroll:true});else canvas.focus({preventScroll:true});lastFocus=null;schedule()}
function exit(direction){closeMemory(false);closePanels();const destination={left:{x:400,y:560,zoom:1.28},forward:{x:1050,y:500,zoom:1.34},right:{x:1310,y:560,zoom:1.28}}[direction];move(destination,1800);$('notice-text').textContent='小路还会继续。下一处花园尚未开放，先在水边走走。';$('notice').hidden=false}
$('open-menu').onclick=()=>{const open=$('options').hidden;closePanels();$('options').hidden=!open;$('open-menu').setAttribute('aria-expanded',String(open))};
$('reset').onclick=reset;$('return').onclick=reset;
$('look-up').onclick=()=>{closeMemory(false);closePanels();move({x:1360,y:250,zoom:1},1700)};
$('close-memory').onclick=()=>closeMemory();
$('open-list').onclick=()=>{closePanels();$('flower-list').hidden=false;$('close-list').focus()};
$('close-list').onclick=()=>{closePanels();$('open-menu').focus()};
document.querySelectorAll('[data-exit]').forEach(b=>b.onclick=()=>exit(b.dataset.exit));
for(const slot of visibleSlots){const m=memoryBySlot.get(slot.id);const b=document.createElement('button');b.textContent=m.title;const date=document.createElement('span');date.textContent=m.date;b.append(date);b.onclick=()=>selectFlower(slot);$('list-items').append(b)}

const pointers=new Map();let dragStart=null,dragDistance=0,pinchDistance=0;
function cancelDemo(){if(demo){demo=null;if(recording){recording.cancelled=true;recording.recorder.stop();}$('record-status').textContent='漫游已停止，可以继续自己探索。'}}
canvas.addEventListener('pointerdown',e=>{cancelDemo();if(selection)closeMemory(false);closePanels();tween=null;canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});dragStart={x:e.clientX,y:e.clientY};dragDistance=0;if(pointers.size===2){const p=[...pointers.values()];pinchDistance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}schedule()});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});dragDistance+=Math.hypot(e.clientX-old.x,e.clientY-old.y);if(pointers.size===2){const p=[...pointers.values()],dist=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(pinchDistance>0)camera.zoom=clamp(camera.zoom*dist/pinchDistance,1,1.65);pinchDistance=dist}else{const s=transform(view,camera).scale;camera.x=clamp(camera.x-(e.clientX-old.x)/s,170,1366);camera.y=clamp(camera.y+(e.clientY-old.y)/s,180,800)}schedule()});
canvas.addEventListener('pointerup',e=>{const click=pointers.size===1&&dragDistance<8;pointers.delete(e.pointerId);if(!pointers.size){pinchDistance=0;dragStart=null}if(click)selectFlower(nearestSlot({x:e.clientX,y:e.clientY},visibleSlots,transform(view,camera),28));schedule()});
canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);pinchDistance=0;dragDistance=100});
canvas.addEventListener('wheel',e=>{e.preventDefault();cancelDemo();tween=null;camera.zoom=clamp(camera.zoom-e.deltaY*.0008,1,1.65);schedule()},{passive:false});
addEventListener('keydown',e=>{if(e.key==='Escape'){cancelDemo();closeMemory();closePanels();return}if(document.activeElement!==canvas)return;const d={ArrowLeft:[-100,0],ArrowRight:[100,0],ArrowUp:[0,-100],ArrowDown:[0,100]}[e.key];if(d){e.preventDefault();cancelDemo();move({x:clamp(camera.x+d[0],170,1366),y:clamp(camera.y+d[1],180,800)},360)}});

function paintLayer(img,factor,offset=0){const t=transform(view,camera,factor);ctx.drawImage(img,t.x+offset,t.y,WORLD.width*t.scale,WORLD.height*t.scale)}
function glow(x,y,r,alpha){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(255,243,202,${alpha})`);g.addColorStop(.25,`rgba(255,236,201,${alpha*.35})`);g.addColorStop(1,'rgba(255,243,212,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function water(time,t){if(reduced)return;ctx.save();ctx.translate(t.x,t.y);ctx.scale(t.scale,t.scale);ctx.beginPath();ctx.moveTo(585,452);ctx.lineTo(1260,447);ctx.lineTo(1360,523);ctx.lineTo(1170,704);ctx.lineTo(1000,596);ctx.lineTo(672,564);ctx.closePath();ctx.clip();for(let i=0;i<26;i++){const y=455+i*8.7;const x=1050+Math.sin(i*4.2)*160+Math.sin(time*.00035+i)*11;ctx.strokeStyle=`rgba(252,241,220,${.06+.045*Math.sin(time*.0007+i)})`;ctx.lineWidth=.65+i*.045;ctx.beginPath();ctx.ellipse(x,y,10+i*.7,1,0,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function particles(time,t){if(reduced)return;for(let i=0;i<8;i++){const x=330+i*123+Math.sin(time*.00023+i)*15,y=480+(i%3)*98+Math.cos(time*.0003+i)*12;const p=project({x,y},t);glow(p.x,p.y,4,Math.max(0,.35*Math.sin(time*.0009+i)))}// Two distant petals, no continuous shower.
 for(let i=0;i<2;i++){const phase=(time*.000028+i*.46)%1;if(phase>.65)continue;const p=project({x:460+i*480+Math.sin(phase*9)*40,y:390+phase*440},t);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(phase*6);ctx.fillStyle='#ead7e365';ctx.beginPath();ctx.ellipse(0,0,3*t.scale,1.6*t.scale,0,0,Math.PI*2);ctx.fill();ctx.restore()}}
function drawButterfly(time,t){let point,progress=0;if(selection&&butterfly){progress=reduced?1:clamp((time-butterfly.start)/butterfly.duration,0,1);const target=project(selection,t);const p=ease(progress);point={x:butterfly.from.x+(target.x-butterfly.from.x)*p,y:butterfly.from.y+(target.y-12-butterfly.from.y)*p-Math.sin(progress*Math.PI)*65};if(progress>=1&&$('memory').hidden)showMemory()}else{point={x:view.w*.72+Math.sin(time*.00023)*25,y:view.h*.4+Math.cos(time*.0004)*16}}const frame=reduced?1:Math.floor(time/135)%4;const a=assets.butterfly;const sw=a.width/4,sy=a.height*.77,sh=a.height*.23;const size=selection?52:40;ctx.save();ctx.globalAlpha=.8;ctx.drawImage(a,frame*sw,sy,sw,sh,point.x-size/2,point.y-size/2,size,size*sh/sw);ctx.restore();if(!reduced&&progress<1){for(let i=1;i<5;i++)glow(point.x-i*6,point.y+i*2,2.4,.16*(1-i/5))}}
function render(time){const dt=lastTime?time-lastTime:0;lastTime=time;if(dt>0&&dt<300){metrics.frames++;if(dt>34)metrics.slowFrames++;metrics.maxFrameMs=Math.max(metrics.maxFrameMs,dt)}if(demo)stepDemo(time);if(tween){const p=ease((time-tween.start)/tween.duration);for(const key of ['x','y','zoom'])camera[key]=tween.from[key]+(tween.to[key]-tween.from[key])*p;if(p>=1)tween=null}ctx.fillStyle='#8a96b8';ctx.fillRect(0,0,view.w,view.h);paintLayer(assets.far,.68);paintLayer(assets.mid,1);const t=transform(view,camera);water(time,t);visibleSlots.forEach((s,i)=>{const p=project(s,t);if(p.x< -30||p.y< -30||p.x>view.w+30||p.y>view.h+30)return;const pulse=reduced?.6:.57+.12*Math.sin(time*.001+i*1.7);glow(p.x,p.y,10*t.scale,pulse);ctx.fillStyle='#fff2cfce';ctx.beginPath();ctx.arc(p.x,p.y,1.5*t.scale,0,Math.PI*2);ctx.fill()});paintLayer(assets.near,1.26,reduced?0:Math.sin(time*.00035)*2);particles(time,t);drawButterfly(time,t);if(recording)recordFrame(time);document.body.dataset.ready='true';}
function tick(time){frameID=0;if(!loaded||!running)return;render(time);if(!reduced||tween||recording||demo)schedule()}
function schedule(){if(!frameID&&loaded&&running)frameID=requestAnimationFrame(tick)}
document.addEventListener('visibilitychange',()=>{running=!document.hidden;lastTime=0;if(!running&&recording)cancelDemo();if(running)schedule()});

// Live Canvas recording, not desktop capture. No microphone or private window is recorded.
// Record the same renderer plus readable equivalents of the DOM title/card/notice.
function wrap(c,text,x,y,maxWidth,lineHeight){let line='';for(const char of text){if(c.measureText(line+char).width>maxWidth){c.fillText(line,x,y);line=char;y+=lineHeight}else line+=char}c.fillText(line,x,y);return y+lineHeight}
function recordFrame(time){const r=recording,c=r.context,w=r.canvas.width,h=r.canvas.height;c.drawImage(canvas,0,0,w,h);const ratio=w/view.w;c.save();c.scale(ratio,ratio);c.fillStyle='#f3f0f1e8';c.fillRect(16,16,158,65);c.fillStyle='#30384b';c.font='22px Camellia';c.fillText('水畔',30,45);c.font='12px Camellia';c.fillText('2.5D · 匿名示例',30,66);if(selection&&!$('memory').hidden){const m=memoryBySlot.get(selection.id),cw=Math.min(380,view.w-36),x=(view.w-cw)/2,y=view.h-282;c.fillStyle='#f5f1f3ed';c.beginPath();c.roundRect(x,y,cw,250,14);c.fill();c.fillStyle='#30384b';c.font='20px Camellia';c.fillText(m.title,x+22,y+42);c.font='14px Camellia';let yy=wrap(c,m.body,x+22,y+78,cw-44,27);c.font='13px Camellia';wrap(c,'「'+m.quote+'」',x+22,yy+15,cw-44,25);c.font='11px Camellia';c.fillText(m.date+' · 匿名示例',x+22,y+225)}else{c.fillStyle='#f5f1f3eb';c.fillRect(16,view.h-60,view.w-32,40);c.fillStyle='#30384b';c.font='12px Camellia';c.fillText(!$('notice').hidden?'下一处尚未开放 · 水边预览':demo?.caption||'轻拖看两岸 · 点花看记忆',30,view.h-35)}c.restore();r.frames++;}
function stepDemo(time){const elapsed=time-demo.start;for(const step of demo.steps){if(!step.done&&elapsed>=step.at){step.done=true;demo.caption=step.caption;step.run()}}if(elapsed>=20000&&recording?.recorder.state==='recording'){recording.elapsed=elapsed;demo=null;recording.recorder.stop()}}
$('record').onclick=async()=>{if(recording)return;if(!canvas.captureStream||!window.MediaRecorder){$('record-status').textContent='这个浏览器不支持录像。请在 Safari 或 Chrome 中打开预览。';return}try{await document.fonts.ready;reset();camera={...origin};tween=null;const rc=document.createElement('canvas');rc.width=Math.min(canvas.width,1280);rc.height=Math.round(rc.width*view.h/view.w);const stream=rc.captureStream(30);const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw Error('没有可用的录像格式');const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5000000});const chunks=[];recording={recorder,canvas:rc,context:rc.getContext('2d'),frames:0,elapsed:0,cancelled:false};recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{const r=recording;recording=null;demo=null;stream.getTracks().forEach(t=>t.stop());document.body.classList.remove('recording');$('record').disabled=false;const blob=new Blob(chunks,{type:mime});const ext=mime.startsWith('video/mp4')?'mp4':'webm';if($('download').href.startsWith('blob:'))URL.revokeObjectURL($('download').href);$('download').href=URL.createObjectURL(blob);$('download').download=`water-garden-${r.cancelled?'partial':'20s'}.${ext}`;$('download').hidden=false;try{if(r.cancelled){$('record-status').textContent='录制已中断，片段可下载。';return}const response=await fetch('/capture',{method:'POST',headers:{'Content-Type':mime,'X-Capture-Frames':String(r.frames),'X-Capture-Duration':String(r.elapsed)},body:blob});if(!response.ok)throw Error('本地服务器不支持保存');$('record-status').textContent='20 秒漫游已保存，可在交接目录查看。'}catch{$('record-status').textContent='录像完成，请点“保存漫游录像”下载。'}finally{$('options').hidden=false;$('open-menu').setAttribute('aria-expanded','true');schedule()}};
 $('record').disabled=true;$('record-status').textContent='正在录制 20 秒漫游；触碰画面可停止。';document.body.classList.add('recording');recorder.start(250);demo={start:performance.now(),caption:'沿水边，慢慢走',steps:[{at:900,caption:'转头看石岸',run:()=>move({x:420,y:575},2000)},{at:3800,caption:'抬头，月亮在这里',run:()=>move({x:1360,y:250},2600)},{at:7500,caption:'沿着水面，回到花丛',run:()=>move({x:760,y:590},1600)},{at:10000,caption:'一朵花，一条记忆',run:()=>selectFlower(slots[16])},{at:14900,caption:'合上记忆，继续走',run:()=>closeMemory()},{at:16600,caption:'小路还会继续',run:()=>exit('left')},{at:18800,caption:'回到水边',run:reset}]};schedule();}catch(error){$('record-status').textContent=`录像未开始：${error.message}`;$('record').disabled=false;document.body.classList.remove('recording')}};

$('retry').onclick=()=>location.reload();
try{await Promise.all(Object.entries({far:'far.png',mid:'midground.png',near:'foreground.png',butterfly:'butterfly-atlas.png'}).map(async([name,file])=>{const img=new Image();img.src=`assets/${file}`;await img.decode();assets[name]=img}));loaded=true;$('loading').hidden=true;schedule()}catch{$('loading').querySelector('p').textContent='花园图片没能打开。请检查连接后重试。';$('retry').hidden=false}
// Read-only QA snapshot, no control API or production integration.
Object.defineProperty(window,'gardenDiagnostics',{get:()=>({loaded,camera:{...camera},reduced,slots:visibleSlots.length,selected:selection?.id??null,cardVisible:!$('memory').hidden,recording:!!recording,metrics:{...metrics},transforms:{far:transform(view,camera,.68),mid:transform(view,camera),near:transform(view,camera,1.26)},projected:visibleSlots.map(s=>({id:s.id,...project(s,transform(view,camera))}))})});
